# shellcheck source=lib/ci-shim.sh
source "$(dirname "${BASH_SOURCE[0]}")/lib/ci-shim.sh"

: "${MDF_MAVEN_GOALS=clean deploy}"
: "${MDF_MAVEN_OPTIONS=-Xmx4096m}"
: "${MDF_SETTINGS_XML=}"
: "${MDF_SKIP_TESTS=True}"

# >>> extracted body
set -euo pipefail
export MAVEN_OPTS="${MDF_MAVEN_OPTIONS}"
# Symlink cached repo to default location so mule-maven-plugin can find it
mkdir -p "$HOME/.m2"
ln -sfn "$(ci_pipeline_workspace)/.m2/repository" "$HOME/.m2/repository"
SKIP_TESTS_FLAG=""
if [ "${MDF_SKIP_TESTS}" = "True" ]; then
  SKIP_TESTS_FLAG="-DskipTests"
fi

SETTINGS="${MDF_SETTINGS_XML}"
M2_REPO="$(ci_pipeline_workspace)/.m2/repository"
SOURCE_POM="$(ci_default_working_directory)/pom.xml"
BUILD_LOG="$(ci_temp_dir)/mvn-build.log"

# Read project version from pom.xml (skip the <parent> block) so we can
# tell whether a deploy failure is an immutable-release conflict.
VERSION=""
if [[ -f "$SOURCE_POM" ]]; then
  PARENT_END_LINE=$(grep -n '</parent>' "$SOURCE_POM" | head -1 | cut -d: -f1)
  if [[ -n "$PARENT_END_LINE" ]]; then
    SEARCH_CONTENT=$(tail -n +"$((PARENT_END_LINE + 1))" "$SOURCE_POM")
  else
    SEARCH_CONTENT=$(cat "$SOURCE_POM")
  fi
  VERSION=$(echo "$SEARCH_CONTENT" | grep '<version>' | head -1 | sed 's/.*<version>\(.*\)<\/version>.*/\1/' | tr -d '[:space:]')
  echo "[DEBUG] Project version: ${VERSION}"
fi

# ──────────────────────────────────────────────────────────────
# Idempotent publish (no pre-probe — keeps the build fast).
# Release (non-SNAPSHOT) versions are immutable on the Azure feed, so a
# retry that re-publishes the same version gets a 409 Conflict. We run the
# deploy once and treat that specific "already exists" failure as success
# (downstream stages reuse the existing artifact). SNAPSHOTs are mutable
# and never hit this path. Any other failure is propagated.
# ──────────────────────────────────────────────────────────────
set +e
mvn ${MDF_MAVEN_GOALS} \
  -s "$SETTINGS" \
  -Dmaven.repo.local="$M2_REPO" \
  $SKIP_TESTS_FLAG 2>&1 | tee "$BUILD_LOG"
RC=${PIPESTATUS[0]}
set -e

if [[ $RC -ne 0 ]]; then
  if [[ -n "$VERSION" && "$VERSION" != *"SNAPSHOT"* ]] && grep -Eiq '(status code: 409|409 conflict|already exists|duplicate)' "$BUILD_LOG"; then
    echo "Release version ${VERSION} already exists on the feed — treating as success (idempotent retry)."
    ci_log_warning "Release version ${VERSION} already published. Skipping re-publish; downstream will reuse the existing artifact."
  else
    ci_log_error "Maven build failed (exit code ${RC})."
    exit $RC
  fi
fi
